guidance.correct_example:
from dataclasses import dataclass, field

@dataclass(frozen=True)
class Config:
    db_url: str
    timeout: int = 30

def process(a_config: Config) -> Result[str]:
    return Result.success(f'Connecting to {a_config.db_url}')

guidance.incorrect_example:
config = {'db_url': 'localhost', 'timeout': 30}

def process() -> Result[str]:
    config['timeout'] = 60
    return Result.success(f'Connecting to {config["db_url"]}')
